// Assuming $ctrl.form has properties like provider, feature, resetScopes,
// tenantCode, tenantApplication, xAuthorizationToken, and redirectUri
const provider = $ctrl.form.provider;
const feature = $ctrl.form.feature;
const resetScopes = $ctrl.form.resetScopes;
const tenantCode = $ctrl.form.tenantCode;
const tenantApplication = $ctrl.form.tenantApplication;
const xAuthorizationToken = $ctrl.form.xAuthorizationToken;
const customRedirectUriInput = $ctrl.form.redirectUri; // Get the input from the form

// Base API URL
const apiBaseUrl = "http://localhost:8080/api/lonti_app_crm/1.0"; // Adjust if this is dynamic

// Construct the base initiate endpoint
const initiateBaseUrl = `${apiBaseUrl}/oauth/initiate`;

// Define the default OAuth callback path (if custom input is not provided)
const defaultOauthCallbackPath = '/TORO/io.toro.lonti-app-crm/e/local/index.html'; // <-- IMPORTANT: Adjust this to your actual default callback route

// Determine the final customRedirectUri to send to the backend
const finalCustomRedirectUri = customRedirectUriInput
    ? customRedirectUriInput // Use the form input if it's not null/empty
    : window.location.origin + defaultOauthCallbackPath; // Otherwise, default to current origin + default path

// Use URL object to safely build query parameters for the /oauth/initiate request
const url = new URL(initiateBaseUrl);

// Add parameters only if they have values
if (provider) {
    url.searchParams.append('provider', provider);
}
if (feature) {
    url.searchParams.append('feature', feature);
}
if (resetScopes) {
    url.searchParams.append('resetScopes', String(resetScopes));
}
// --- ADD THE customRedirectUri PARAMETER HERE (using the determined value) ---
url.searchParams.append('customRedirectUri', finalCustomRedirectUri);
// --- END ADDITION ---


// Convert the URL object back to a string
const finalInitiateUrl = url.toString();

const headers = {
    "Accept": "application/json",
    "X-TENANT-CODE": tenantCode,
    "X-TENANT-APPLICATION": tenantApplication,
    "X-Authorization": xAuthorizationToken
};

try {
    const response = await fetch(finalInitiateUrl, { // Use the constructed URL
        method: "GET",
        headers: headers,
    });

    if (!response.ok) {
        const errorText = await response.text();
        console.error(`HTTP error! Status: ${response.status}`, errorText);
        throw new Error(`Failed to initiate OAuth: ${response.statusText}`);
    }

    const data = await response.json();
    console.log("OAuth Initiation Success:", data);

    if (data.externalAuthServerUrl) {
        console.log("Redirecting to:", data.externalAuthServerUrl);
        window.location.href = data.externalAuthServerUrl;
    } else {
        console.warn("External authentication server URL not found in response.");
    }

    return data;

} catch (error) {
    console.error("Error during OAuth initiation fetch:", error);
    // Handle the error in your UI, e.g., show a toast message
}

// Extract URL parameters from the current window's URL
const urlParams = new URLSearchParams(window.location.search);
const code = urlParams.get('code');
const state = urlParams.get('state');
const scope = urlParams.get('scope'); // Scope might be long, depending on what was requested

// If 'code' or 'state' are missing, something went wrong with the OAuth flow.
// Log an error and exit.
if (!code || !state) {
    console.error("OAuth callback error: Missing 'code' or 'state' parameters in URL.");
    // Consider a user-facing toast/message here.
    return;
}

// Define your backend API base URL
const apiBaseUrl = "http://localhost:8080/api/lonti_app_crm/1.0"; // Adjust if dynamic

// Construct the base callback endpoint
const baseCallbackEndpoint = `${apiBaseUrl}/oauth/${$ctrl.form.provider}/callback`;

// Define the default customRedirectUri path
const defaultCustomRedirectUriPath = '/TORO/io.toro.lonti-app-crm/e/local/index.html'; // Your specific index.html path

// Determine the final customRedirectUri to send to the backend
const finalCustomRedirectUri = $ctrl.form.redirectUri // Check if form input provides it
    ? $ctrl.form.redirectUri
    : window.location.origin + defaultCustomRedirectUriPath; // Otherwise, default to current origin + default path

// --- Construct the full callback URL with dynamic query parameters ---
const callbackUrl = new URL(baseCallbackEndpoint); // Create a URL object

callbackUrl.searchParams.append('code', code);
callbackUrl.searchParams.append('state', state);
if (scope) {
    callbackUrl.searchParams.append('scope', scope);
}
// Add the customRedirectUri as a parameter (using the determined value)
callbackUrl.searchParams.append('customRedirectUri', finalCustomRedirectUri);

// Convert the URL object back to a string for the fetch request
const finalCallbackUrl = callbackUrl.toString();
// --- End URL construction ---

try {
    const response = await fetch(finalCallbackUrl, {
        method: "GET", // Using GET as per your request
        headers: {
            "Accept": "application/json",
            "X-TENANT-CODE": $ctrl.form.tenantCode, // Assuming this is from form
            "X-TENANT-APPLICATION": $ctrl.form.tenantApplication, // Assuming this is from form
            ...($ctrl.form.xAuthorizationToken && { "X-Authorization": $ctrl.form.xAuthorizationToken })
        },
    });

    if (!response.ok) {
        const errorData = await response.json(); // Assuming backend sends JSON for errors
        console.error(`Callback HTTP error! Status: ${response.status}`, errorData);
        // Display specific error messages from backend
        // e.g., $ctrl.utilityService.toast(errorData.message || "Authentication failed on callback.", "ERROR");
        throw new Error(`Callback failed: ${errorData.message || response.statusText}`);
    }

    const data = await response.json();
    console.log("OAuth Callback Success:", data);

    // Your logic to store tokens and redirect to the dashboard
    // e.g., localStorage.setItem('authToken', data.authToken);
    // window.location.href = '/dashboard';

    return data;

} catch (error) {
    console.error("Error sending OAuth callback data:", error);
    // Display a general error message to the user
    // e.g., $ctrl.utilityService.toast("An unexpected error occurred during authentication.", "ERROR");
}
